<?php use App\UI\UI as U; use App\UI\Fulfillment as F;
$orders=array_values(array_filter($data['sample']['orders'],fn($o)=>$o[7]==='pickup')); ?>
<?= U::heading('Pickup queue','Prepare water for collection at '.$info['caption'].'.') ?>
<?php $by = fn($st) => (string)count(array_filter($orders, fn($o) => F::status($o) === $st)); ?>
<div class="mb-4 grid grid-cols-2 gap-3 xl:grid-cols-3 max-xl:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Pickup orders',(string)count($orders),'store','blue','Collected at the station','Total') ?><?= U::stat('Waiting',$by('Confirmed'),'clock','amber','Confirmed, not yet refilled','Confirmed') ?><?= U::stat('Ready for pickup',$by('Ready for pickup'),'check','green','Customer can collect now','Ready') ?></div>
<p class="mb-4 flex items-center gap-2 rounded-xl border border-line bg-foam px-3.5 py-2.5 text-sm"><?= U::icon('shield','size-4 shrink-0 text-water') ?>Local preview only. Confirmations update this browser’s sample queue; customers are not notified.</p>
<section class="panel p-4 md:p-5"><div class="mb-4 grid gap-3 sm:grid-cols-2"><?= U::field('Search pickups','pickup-search','','search',['icon'=>'search','data-search'=>'pickup-orders','placeholder'=>'Order or customer']) ?><?= U::select('Pickup status','pickup-status',['all'=>'All statuses','Confirmed'=>'Confirmed','Ready for pickup'=>'Ready for pickup','Picked up'=>'Picked up'],'all',['data-filter-target'=>'pickup-orders']) ?></div>
<div class="overflow-x-auto"><table id="pickup-orders" class="data-table"><thead><tr><?php foreach(['Order','Customer','Containers','Requested','Status','Actions'] as $h): ?><th><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($orders as $o): ?><tr data-search-row data-filter-value="<?= U::e(F::status($o)) ?>"><td class="font-semibold"><?= U::e($o[0]) ?></td><td><?= U::e($o[1]) ?><p class="flex items-center gap-1 text-xs text-muted"><?= U::icon('credit','size-3.5') ?>Cash on pickup</p></td><td><?= $o[3] ?></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('clock','size-4 text-muted') ?><?= U::e($o[6]) ?></span></td><td><span id="pickup-status-<?= $o[0] ?>"><?= U::badge(F::status($o)) ?></span></td><td><div class="flex flex-wrap gap-2"><?= U::btn('Mark ready','','secondary','check',['class'=>'btn-sm','data-status'=>'Ready for pickup','data-status-target'=>'pickup-status-'.$o[0]]) ?><?= U::btn('Confirm collection','','primary','store',['class'=>'btn-sm','data-status'=>'Picked up','data-status-target'=>'pickup-status-'.$o[0]]) ?><?= U::btn('View','/station-admin/orders?order='.$o[0],'ghost','eye',['class'=>'btn-sm']) ?></div></td></tr><?php endforeach; ?></tbody></table><p data-empty hidden class="p-5 muted">No pickups match your search.</p></div></section>
